const n=(v)=>{if(v===undefined||v===null||v==='')return null;const x=Number(String(v).replace(',','.'));return Number.isFinite(x)?x:null};
const fmt=(v,d=0)=>v===null||v===undefined||!Number.isFinite(v)?'—':new Intl.NumberFormat('es-ES',{minimumFractionDigits:d,maximumFractionDigits:d}).format(v);
const avg=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null;
const sum=a=>a.reduce((x,y)=>x+(Number(y)||0),0);
