const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',activity:'<path d="M22 12h-4l-3 8L9 4l-3 8H2"/>',moon:'<path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z"/>',chart:'<path d="M3 3v18h18"/><path d="m7 15 4-4 3 2 5-7"/>',coach:'<path d="M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.2 2.2m8.4 8.4 2.2 2.2m0-12.8-2.2 2.2m-8.4 8.4-2.2 2.2"/><circle cx="12" cy="12" r="4"/>',food:'<path d="M4 3v7a3 3 0 0 0 6 0V3M7 3v18M17 21v-8h-3V8a5 5 0 0 1 5-5v18"/>',settings:'<path d="M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.9l.1.1-2 2-.1-.1a1.7 1.7 0 0 0-1.9-.34 1.7 1.7 0 0 0-1.07 1.56V21h-2.85v-.15A1.7 1.7 0 0 0 10.85 19a1.7 1.7 0 0 0-1.9.34l-.1.1-2-2 .1-.1A1.7 1.7 0 0 0 6.6 15a1.7 1.7 0 0 0-1.56-1.07H5v-2.85h.15A1.7 1.7 0 0 0 6.6 10a1.7 1.7 0 0 0-.34-1.9l-.1-.1 2-2 .1.1A1.7 1.7 0 0 0 10.85 6a1.7 1.7 0 0 0 1.07-1.56V4h2.85v.15A1.7 1.7 0 0 0 16 5.6a1.7 1.7 0 0 0 1.9-.34l.1-.1 2 2-.1.1A1.7 1.7 0 0 0 19.4 10a1.7 1.7 0 0 0 1.56 1.07H21v2.85h-.15A1.7 1.7 0 0 0 19.4 15Z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',dumbbell:'<path d="m6.5 6.5 11 11M3 8l5-5m8 18 5-5M2 11l9-9m2 20 9-9"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',plus:'<path d="M12 4v16M4 12h16"/>',spark:'<path d="m12 3 2.2 6.8L21 12l-6.8 2.2L12 21l-2.2-6.8L3 12l6.8-2.2L12 3Z"/>',alert:'<path d="m12 3-10 18h20L12 3Z"/><path d="M12 9v4m0 4h.01"/>',check:'<path d="M20 6 9 17l-5-5"/>',trash:'<path d="M4 7h16M10 11v7m4-7v7M6 7l1 14h10l1-14M9 7V4h6v3"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1"/><path d="m3 17 5-5 4 4 3-3 6 5"/>',layers:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 3v18"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5m-4 0h8"/>',speaker:'<path d="M11 5 6 9H2v6h4l5 4V5Z"/><path d="M15 9a5 5 0 0 1 0 6m3-9a9 9 0 0 1 0 12"/>',uploadAudio:'<path d="M9 18V5l12-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/>',download:'<path d="M12 3v13m-4-4 4 4 4-4M4 18v3h16v-3"/>'};
const ic=(name,size=18)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.grid}</svg>`;
const NAV=[['overview','Mi panel','grid'],['sessions','Entrenamientos','activity'],['recovery','Recuperación','moon'],['nutrition','Alimentación','food'],['analytics','Estadísticas','chart'],['assistant','Asistente IA','coach'],['settings','Ajustes','settings']];
const TYPES={team:'Fútbol · equipo',individual:'Fútbol · individual',game:'Partido',gym:'Gimnasio · fuerza',speed:'Velocidad / sprint',plyo:'Pliometría',recovery:'Recuperación activa',other:'Otro entrenamiento'};
const FIELDS={distance:'Distancia total (km)',sprint:'Distancia sprint (m)',top:'Velocidad máxima (km/h)',accel:'Aceleraciones (nº)',decel:'Desaceleraciones (nº)',meteorLoad:'Carga del Meteor (unidad original)'};
const sessionLoad=s=>(n(s.duration)!=null&&n(s.rpe)!=null)?n(s.duration)*n(s.rpe):null;
const inRange=(iso,days,end=today())=>daysBetween(iso,end)>=0&&daysBetween(iso,end)<days;
const sortedSessions=()=>[...store.sessions].sort((a,b)=>b.date.localeCompare(a.date)||String(b.id).localeCompare(String(a.id)));
const lastCheckin=(date=today())=>store.checkins.find(x=>x.date===date)||null;
const sortedCheckins=()=>[...store.checkins].sort((a,b)=>b.date.localeCompare(a.date));
const sessionAtDate=(date)=>store.sessions.filter(s=>s.date===date);
const weeklyLoad=(days=7,end=today())=>sum(store.sessions.filter(s=>inRange(s.date,days,end)).map(sessionLoad));
const meanSleep=(days=7)=>avg(store.checkins.filter(c=>inRange(c.date,days)&&n(c.sleepHours)!=null).map(c=>n(c.sleepHours)));
const sprint7=()=>sumMeasured(store.sessions.filter(s=>inRange(s.date,7)).map(s=>s.gps?.sprint));
const maxSpeed=(days=28)=>{const a=store.sessions.filter(s=>inRange(s.date,days)).map(s=>n(s.gps?.top)).filter(x=>x!=null);return a.length?Math.max(...a):null};
function calcWellness(c){if(!c)return {score:null,count:0};const pos=['energy','motivation'],neg=['fatigue','soreness','legs'];const values=[...pos.map(k=>n(c[k])!=null?25*(n(c[k])-1):null),...neg.map(k=>n(c[k])!=null?25*(5-n(c[k])):null)].filter(x=>x!=null);return {score:values.length>=3?Math.round(avg(values)):null,count:values.length}}
function calcRecoveryHabits(c){
 if(!c)return {score:null,coverage:0,parts:[]};const target=n(store.profile.sleepTarget)||9,h=n(c.sleepHours),qual=n(c.sleepQuality);
 const ss=h===null?null:clamp(.75*clamp(h/target*100)+.25*(qual===null?clamp(h/target*100):25*(qual-1)));
 const a=[c.nutritionRating,c.hydrationRating].map(n).filter(v=>v!==null);
 const components=[['Sueño',40,ss],['Nutrición e hidratación',25,a.length?25*(avg(a)-1):null],['Recuperación activa',15,n(c.activeRating)!=null?25*(n(c.activeRating)-1):null],['Movilidad y cuidados',10,n(c.mobilityRating)!=null?25*(n(c.mobilityRating)-1):null],['Descanso y gestión',10,n(c.restRating)!=null?25*(n(c.restRating)-1):null]];
 let knownWeight=sum(components.filter(x=>x[2]!=null).map(x=>x[1]));
 return {score:knownWeight>=65?Math.round(sum(components.filter(x=>x[2]!=null).map(x=>x[1]*x[2]))/knownWeight):null,coverage:knownWeight,parts:components.map(([name,weight,score])=>({name,weight,score}))}
}
function stateOf(c){if(!c)return {label:'Sin check-in',tone:'blue',explanation:'Completa tu registro de la mañana'};const w=calcWellness(c).score;if(n(c.painScale)!=null&&n(c.painScale)>=4)return {label:'Revisar molestias',tone:'red',explanation:'Se han registrado molestias significativas'};if(w===null)return {label:'Datos insuficientes',tone:'blue',explanation:'Registra energía, fatiga y sensaciones'};const refs=store.checkins.filter(x=>x.date<c.date&&inRange(x.date,28,c.date)).map(calcWellness).map(x=>x.score).filter(x=>x!==null),base=refs.length>=5?avg(refs):null;
 if((base!=null&&w<base-15)||w<40)return {label:'Fatiga a vigilar',tone:'orange',explanation:'Bienestar por debajo del patrón de referencia'};
 if(w>=70&&(base==null||w>=base-10))return {label:'Sensaciones favorables',tone:'mint',explanation:'Bienestar actual favorable; revisar siempre el contexto'};
 return {label:'Estado intermedio',tone:'blue',explanation:'Interpretar junto con sueño, carga y molestias'};
}
function strengthChange(exercise,date){const prev=store.sessions.filter(s=>s.date<date||s.date===date).flatMap(s=>(s.exercises||[]).map(e=>({date:s.date,sid:s.id,...e}))).filter(e=>String(e.name||'').trim().toLowerCase()===String(exercise.name||'').trim().toLowerCase()&&n(e.weight)>0).sort((a,b)=>b.date.localeCompare(a.date)||String(b.sid).localeCompare(String(a.sid)));const x=prev.find(e=>e.sid!==exercise.sid);return x?{previous:n(x.weight),change:n(exercise.weight)!=null?Math.round((n(exercise.weight)/n(x.weight)-1)*1000)/10:null}:null}
function recs(){const result=[],c=lastCheckin(),prevDate=dateOffset(today(),-1),prev=store.sessions.filter(s=>s.date===prevDate),prevLoad=sum(prev.map(sessionLoad));const s=stateOf(c);const active7=store.sessions.filter(x=>inRange(x.date,7));const heavy=(prevLoad>0&&prevLoad>=Math.max(550,weeklyLoad()/Math.max(1,new Set(active7.map(s=>s.date)).size)*1.25));
 if(c&&n(c.painScale)>=4)result.push({level:'alert',title:'Molestias registradas: no las ignores',body:'Evita añadir carga que provoque dolor y coméntalo con tu entrenador o un profesional sanitario, especialmente si empeora o limita el movimiento.'});
 if(c&&n(c.sleepHours)!=null&&n(c.sleepHours)<8)result.push({level:'warning',title:'Prioriza el sueño esta noche',body:`Has registrado ${fmt(n(c.sleepHours),1)} h. Para adolescentes suele recomendarse dormir 8–10 h; intenta organizar una noche suficiente y regular.`});
 if(c&&((n(c.legs)>=4)||(n(c.soreness)>=4)))result.push({level:'warning',title:'Piernas cargadas: recuperación sin exigir más',body:'Si no hay dolor ni contraindicación, prueba 10–20 min de paseo o bicicleta muy suave y movilidad cómoda. Descansar también es válido; comprueba después cómo respondes.'});
 if(heavy)result.push({level:'warning',title:'Revisa la carga adicional',body:`Ayer acumulaste ${fmt(prevLoad)} UA estimadas. Considera evitar añadir trabajo intenso individual sin revisar el calendario y tus sensaciones.`});
 if(prev.some(s=>s.type==='gym'&&s.exercises?.length))result.push({level:'normal',title:'Comprueba la respuesta a la fuerza',body:'Ayer hubo trabajo de fuerza. Registra agujetas, pesadez, sueño y sensación de rendimiento antes de decidir si añades otra sesión intensa.'});
 if(c&&n(c.nutritionRating)!=null&&n(c.nutritionRating)<=2)result.push({level:'normal',title:'Mejora la recuperación nutricional',body:'Planifica una comida suficiente con fuentes de hidratos de carbono y proteínas, además de agua. Evita restringir comidas por tratarse de un día suave.'});
 if(!c)result.push({level:'normal',title:'Empieza por tu check-in',body:'Registra sueño, energía, fatiga y molestias. Esos datos permiten interpretar la carga de ayer sin inventar conclusiones.'});
 if(!prev.length&&store.sessions.length)result.push({level:'normal',title:'Registra toda la carga',body:'No hay sesión registrada ayer. Puedes haber descansado o faltar un entrenamiento; confírmalo para interpretar mejor tu recuperación.'});
 const gapToMatch=store.profile.nextGame?daysBetween(today(),store.profile.nextGame):null;
 if(gapToMatch!=null&&gapToMatch>=0&&gapToMatch<=1)result.push({level:'normal',title:'Partido próximo: prioriza llegar preparado',body:'Tienes un partido en las próximas 24–48 horas según tu calendario. Evita sumar trabajo exigente no planificado y coordina cualquier cambio con el entrenador.'});
 if(!result.length)result.push({level:'normal',title:'Mantén la planificación y escucha tus sensaciones',body:'No aparecen señales destacadas en los registros actuales. Sigue el plan del entrenador, cuida sueño y alimentación y evita añadir sesiones solo por una buena puntuación.'});
 return result;
}
function nutritionRecs(){const todays=store.sessions.filter(s=>s.date===today()),recent=store.sessions.filter(s=>inRange(s.date,2)),hasGame=todays.some(x=>x.type==='game')||recent.some(x=>x.type==='game'),hard=todays.some(s=>sessionLoad(s)>=450)||recent.some(s=>sessionLoad(s)>=650);const c=lastCheckin();const a=[];
 if(hasGame)a.push({title:'Después de competir',body:'Prioriza una comida suficiente: patata, arroz, pasta o pan, junto con pescado, huevos, legumbres u otra proteína, vegetales y líquidos.'});
 else if(hard)a.push({title:'Día de carga importante',body:'Organiza una comida con hidratos de carbono y proteínas: por ejemplo arroz con pollo o tofu y verduras, más fruta y agua.'});
 else a.push({title:'Alimentación cotidiana completa',body:'Mantén comidas regulares con cereales o tubérculos, verduras, frutas, alimentos proteicos y agua; no hace falta restringir por descansar.'});
 if(c&&n(c.hydrationRating)!=null&&n(c.hydrationRating)<=2)a.push({title:'Hidratación a revisar',body:'Distribuye el consumo de agua durante el día y alrededor del entrenamiento; con calor o mucho sudor, adapta la reposición a las condiciones.'});
 a.push({title:'Antes del próximo entrenamiento',body:'Según el tiempo disponible, considera un bocadillo, yogur con fruta, avena u otra opción fácil de tolerar. Ajusta la cantidad a tu apetito y horario.'});return a;
}
function dSeries(field='load',days=7){let a=[];for(let j=days-1;j>=0;j--){const d=dateOffset(today(),-j),ses=sessionAtDate(d),check=lastCheckin(d);let v=field==='load'?sumMeasured(ses.map(sessionLoad)):field==='sprint'?sumMeasured(ses.map(s=>s.gps?.sprint)):field==='sleep'?n(check?.sleepHours):field==='wellness'?calcWellness(check).score:field==='distance'?sumMeasured(ses.map(s=>s.gps?.distance)):null;a.push({date:d,val:v});}return a}
function chartBar(data,{height=200,color='#b8f26a',unit='',emptyText='Aún no hay datos'}={}){if(!data.length||data.every(x=>!x.val)){return `<div class="empty"><div class="empty-icon">${ic('chart',23)}</div>${emptyText}</div>`}const W=680,H=height,top=15,bottom=34,left=39,right=8,innerW=W-left-right,innerH=H-top-bottom,max=Math.max(...data.map(x=>x.val||0),1)*1.15,gap=innerW/data.length,barW=Math.max(4,Math.min(36,gap*.58));let g='';for(let i=0;i<4;i++){let y=top+i*innerH/3;g+=`<line class="chart-grid" x1="${left}" x2="${W-right}" y1="${y}" y2="${y}"/><text class="chart-zero" x="2" y="${y+4}">${fmt(max*(1-i/3))}${unit}</text>`}let b=data.map((x,i)=>{let hh=(x.val||0)/max*innerH,xx=left+i*gap+gap/2-barW/2;return `<rect x="${xx}" y="${top+innerH-hh}" width="${barW}" height="${Math.max(hh,1.5)}" rx="4" fill="${color}" opacity="${x.val?1:.28}"><title>${x.date}: ${fmt(x.val,fieldDigits(x.val))}${unit}</title></rect>${(i%(data.length>14?Math.ceil(data.length/7):1)===0)?`<text class="chart-label" x="${xx+barW/2}" y="${H-8}" text-anchor="middle">${shortDate(x.date)}</text>`:''}`}).join('');return `<div class="chart-wrap"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Gráfico de barras con valores diarios">${g}${b}</svg></div>`}
function fieldDigits(v){return v!=null&&v%1!==0?1:0}
function chartLine(data,{height=195,color='#62aafa',suffix=''}={}){if(data.filter(x=>x.val!=null).length<2)return `<div class="empty"><div class="empty-icon">${ic('chart',23)}</div>Necesitamos más registros para dibujar una tendencia.</div>`;const W=680,H=height,left=44,right=11,top=15,bottom=35,innerW=W-left-right,innerH=H-top-bottom,values=data.map(x=>x.val).filter(v=>v!=null),lo=Math.min(...values,0),hi=Math.max(...values,1)*1.08,scale=v=>top+innerH-(v-lo)/(hi-lo||1)*innerH,x=(i)=>left+(i*innerW/(data.length-1));let lines='';let seg=[];data.forEach((r,i)=>{if(r.val!=null)seg.push([x(i),scale(r.val)]);else{if(seg.length>1)lines+=`<polyline points="${seg.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`;seg=[]}});if(seg.length>1)lines+=`<polyline points="${seg.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`;let g='';for(let i=0;i<4;i++){const y=top+i*innerH/3;g+=`<line class="chart-grid" x1="${left}" x2="${W-right}" y1="${y}" y2="${y}"/><text class="chart-zero" x="4" y="${y+4}">${fmt(hi-(hi-lo)*i/3,1)}${suffix}</text>`}const dots=data.map((r,i)=>r.val==null?'':`<circle cx="${x(i)}" cy="${scale(r.val)}" r="3.6" fill="${color}"><title>${r.date}: ${fmt(r.val,1)}${suffix}</title></circle>`).join('');const label=data.map((r,i)=>i%(data.length>14?Math.ceil(data.length/7):1)===0?`<text class="chart-label" text-anchor="middle" x="${x(i)}" y="${H-8}">${shortDate(r.date)}</text>`:'').join('');return `<div class="chart-wrap"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Gráfico de tendencia">${g}${lines}${dots}${label}</svg></div>`}
